python -c "from alloy_refine import *; from sklearn.model_selection import RepeatedKFold; splits=list(RepeatedKFold(n_splits=5,n_repeats=5,random_state=175).split(X)); chosen={'poly2':additive_model(nums,degree=2),'poly2Fe':additive_model(nums+['Fe'],degree=2),'poly3':additive_model(nums,degree=3),'spline3':additive_model(nums,knots=3)}; results={}; print('REPEATED VALIDATION'); 
for name,m in chosen.items():
 err=[]; pred=[]
 for a,b in splits:
  m.fit(XF.iloc[a],y[a]); err.extend((y[b]-m.predict(XF.iloc[b]))**2); pred.append(m.predict(PF))
 print(name,'RMSE',round(np.mean(err)**.5,3)); results[name]=np.array(pred)
 for i in [72,8,21,69,52,75]:
  print(pool.candidate_id.iloc[i], 'mean',round(results[name][:,i].mean(),1),'split_sd',round(results[name][:,i].std(),1))"

python -c "from alloy_validate import *; selected=['additive_Fe','numeric_interactions','all_interactions']; fixed=[]; points=[]
for name in selected:
 m=chosen[name].fit(XF,y); points.append(m.predict(PF)); alpha=m[-1].alpha_; m.steps[-1]=('ridge',Ridge(alpha=alpha)); fixed.append(m)
rng=np.random.default_rng(612); draws=[]
for k in range(250):
 ix=rng.integers(0,len(y),len(y)); pred=[]
 for m in fixed:
  m.fit(XF.iloc[ix],y[ix]); pred.append(m.predict(PF))
 draws.append(np.mean(pred,axis=0))
draws=np.array(draws); point=np.mean(points,axis=0); top5=np.argsort(draws,axis=1)[:,-5:]; best=np.argmax(draws,axis=1); print('BOOTSTRAP STABILITY (250 resamples, model estimates only)')
for i in np.argsort(point)[::-1][:8]:
 print(pool.candidate_id.iloc[i], 'full_prediction',round(point[i],2),'bootstrap_sd',round(draws[:,i].std(),2),'top5_frequency',round(np.mean((top5==i).any(axis=1)),3),'best_frequency',round(np.mean(best==i),3))
print('P(c069>c021)',np.mean(draws[:,69]>draws[:,21])); print('P(c021>c052)',np.mean(draws[:,21]>draws[:,52])); print('P(c072>c008)',np.mean(draws[:,72]>draws[:,8]))"

